-- Independent Dadyoom teaching supports, not claims about the contents of official books.
-- Idempotent: update only genuinely empty published lessons; add each origin/type once.
DO $dadyoom$
DECLARE
  r RECORD;
  target_id uuid;
  target_content text;
BEGIN
  FOR r IN SELECT * FROM jsonb_to_recordset('[{"n":1,"skill":"التفريق بين الأمل والخطة الواقعية","passage":"في نص تدريبي كتب طالبان هدفين: تمنى الأول الفوز بمسابقة مهنية، بينما وضع الثاني خطة تدريب أسبوعية وسجل ما يتعلمه. يختلف الحلم عن الإجراء القابل للقياس، لكن هذا المثال لا يمثل نص «الشباب بين الواقع والآمال» الرسمي.","prompt":"أي فعل يدل على تحويل الأمل إلى خطة؟","correct":"التدريب الأسبوعي وتسجيل التقدم","w1":"الاكتفاء بالتمني","w2":"ترك التجربة","w3":"حذف الهدف","practice":"اكتب فقرة تقارن بين أمنية ومشروع مهني ممكن، واضعًا خطوتين ومؤشر نجاح معقولًا."},{"n":2,"skill":"المبني للمعلوم والمبني للمجهول","passage":"«صنعَ العاملُ النموذجَ» فعل ماض مبني للمعلوم مع فاعل. عند بناء الفعل للمجهول نقول «صُنِعَ النموذجُ» فيُحذف الفاعل ويُرفع «النموذجُ» نائب فاعل. تتغير بنية الفعل ودور الاسم، دون تغيير حدوث الصنع.","prompt":"ما إعراب «النموذجُ» في «صُنِع النموذجُ»؟","correct":"نائب فاعل مرفوع","w1":"فاعل الفعل المبني للمعلوم","w2":"مفعول به منصوب","w3":"مضاف إليه","practice":"حوّل ثلاث جمل من المعلوم إلى المجهول، وحدد نائب الفاعل وحركة أول الفعل وما قبل آخره."},{"n":3,"skill":"حوار حجاجي متوازن","passage":"في حوار مستقل دافع متدرب عن استخدام الأجهزة اللوحية لأنها تُسهّل الرجوع إلى التعليمات، واعترض آخر بسبب احتمال تشتت الانتباه. اتفقا على استخدامها خلال نشاط محدد وتحت إشراف المعلم. يدعم كل طرف موقفه بسبب ويرد باحترام.","prompt":"ما نتيجة الحوار بين الطرفين؟","correct":"استخدام منضبط للأجهزة أثناء نشاط محدد","w1":"منع أي تعلم","w2":"إهمال الاعتراض","w3":"التخلي عن المناقشة","practice":"اكتب حوارًا من ثماني مداخلات حول وسيلة تعلم مهنية، يتضمن حجتين واعتراضًا وردًا واضحًا."},{"n":4,"skill":"تذوق القصيدة مع توثيق شاهد صحيح","passage":"قراءة «تحية للشباب» لأحمد رفيق المهدوي تتطلب الرجوع إلى القصيدة قبل الاستشهاد أو تحديد قصد الشاعر. مثال نثري مستقل: «يتعلم الشاب مهارة ويشارك المجتمع ثم يعود إلى التدريب كلما أخطأ». يشجع النص على المبادرة ولا ينتسب إلى القصيدة.","prompt":"ما السلوك الدال على المثابرة في المثال؟","correct":"العودة إلى التدريب بعد الخطأ","w1":"التوقف النهائي","w2":"رفض المشاركة","w3":"إهمال المهارة","practice":"استخرج بيتًا موثقًا من قصيدة «تحية للشباب» يدعم قيمة تربوية، واشرح عاطفته بألفاظك."},{"n":5,"skill":"الخبر والإنشاء: التمييز الأساسي","passage":"«الورشةُ منظمةٌ» جملة خبرية تحتمل الصدق أو الكذب بحسب الواقع. «رتّبْ أدواتك» إنشاء طلبي لا يُحكم عليه بالصدق أو الكذب في لحظة الطلب. يتطلب التصنيف النظر إلى غرض العبارة وسياقها.","prompt":"أي عبارة إنشائية طلبية؟","correct":"رتّب أدواتك","w1":"الورشة منظمة","w2":"الطالب حضر مبكرًا","w3":"الأداة جديدة","practice":"اكتب ست عبارات عن التدريب، ثلاثًا خبرية وثلاثًا إنشائية، ثم علل تصنيف كل واحدة."},{"n":6,"skill":"مناقشة العمل التطوعي واقعيًا","passage":"اقترح طالبان إصلاح مقاعد مكتبة المدرسة تحت إشراف المختصين؛ حددا عدد المقاعد المطلوب إصلاحها وموعدًا لجمع الملاحظات. لا يكفي الإعلان عن المبادرة دون تحديد السلامة والموارد والأثر.","prompt":"ما الخطوة التي تجعل أثر المبادرة قابلا للمتابعة؟","correct":"حصر المقاعد ومراجعة النتيجة","w1":"الاكتفاء بالصور","w2":"عدم إشراك المختصين","w3":"تجاهل إجراءات السلامة","practice":"أنشئ حوارًا قصيرًا يقترح مشروعًا تطوعيًا، مع أدوار واضحة ومخاطر وإجراءات احترازية."},{"n":7,"skill":"قراءة التراث السردي دون نسبة أحداث مختلقة","passage":"يتطلب نص «من أعاجيب أهل مرو» للجاحظ الاطلاع على النص للتحقق من الشخصيات والمفارقة وأسلوب السرد. تدريب مستقل: «أغلق الرجل صندوقه بإحكام ثم طلب إلى جاره أن يصف ما بداخله». تكمن المفارقة في طلب وصف ما لا يمكن رؤيته؛ ليست حادثة من كتاب الجاحظ.","prompt":"أين المفارقة في المثال المستقل؟","correct":"طلب وصف شيء داخل صندوق مغلق","w1":"إغلاق الصندوق","w2":"حديث الرجل مع جاره","w3":"وجود صندوق","practice":"بعد قراءة نص الجاحظ حدّد موقفًا ساخرًا حقيقيًا بدليل نصي، واشرح وظيفة المفارقة."},{"n":8,"skill":"أركان التشبيه وأثره","passage":"«المتدربُ كالنحلةِ في نشاطه» تشبيه مرسل مفصل: المشبّه «المتدرب»، المشبّه به «النحلة»، الأداة «الكاف»، ووجه الشبه «النشاط». حذف الأداة أو وجه الشبه يغيّر نوع التشبيه بحسب الأركان الموجودة.","prompt":"ما وجه الشبه في المثال؟","correct":"النشاط","w1":"المتدرب","w2":"النحلة","w3":"الكاف","practice":"كوّن أربعة تشبيهات في سياقات تعليمية، وحدد الأركان ثم اشرح أثر حذف الأداة أو وجه الشبه."},{"n":9,"skill":"كتابة تعليمات السلامة بصيغة واضحة","passage":"في بطاقة أصلية للتدريب: «افصل الكهرباء قبل الفحص، وافحص سلامة التوصيلات، وأبلغ المشرف إذا لاحظت تلفًا، ولا تستخدم جهازًا معطّلًا». ترتيب الخطوات وصيغ الأمر والنهي يساعدان على الفهم ويقللان الالتباس.","prompt":"ما أول إجراء في البطاقة؟","correct":"فصل الكهرباء قبل الفحص","w1":"تشغيل الجهاز المعطل","w2":"تجاهل المشرف","w3":"تجاوز المعاينة","practice":"اكتب ست تعليمات مرتبة للسلامة في نشاط تعرفه، مع تمييز الإلزام والتحذير والتحقق."},{"n":10,"skill":"التحليل السردي بمصدر صحيح","passage":"نص «أعيتني فيك الحيلة» المنسوب في العنوان إلى ابن عبد ربه يحتاج مراجعة المصدر قبل تلخيص أحداثه. في مثال مستقل قال المتعلم: «حاولت إقناع زميلي مرات، فاقترحت في النهاية أن نجرب رأيينا ونقارن النتائج». يبيّن تحولًا في استراتيجية حل النزاع.","prompt":"ما التحول الذي حدث في موقف المتعلم؟","correct":"الانتقال إلى تجربة الحلول ومقارنة النتائج","w1":"التوقف عن الحوار","w2":"فرض رأي واحد","w3":"ترك السؤال بلا جواب","practice":"بعد قراءة النص الأصلي حدد حدثين وشاهدًا للتغير في الموقف، ثم اكتب ملخصًا دون اختلاق شخصيات."},{"n":11,"skill":"الخبر والإنشاء: غرض الاستفهام والنداء","passage":"في «هل تحققتَ من سلامة الجهاز؟» استفهام قد يقصد به طلب المعلومة، و«يا زميلي، راجع القائمة» نداء يعقبه أمر إرشادي. تتحدد أغراض الأساليب من السياق، فلا يصح جعل كل سؤال توبيخًا.","prompt":"ما الأسلوب في «يا زميلي»؟","correct":"نداء","w1":"خبر مثبت","w2":"تشبيه","w3":"جناس","practice":"اكتب حوارًا يحتوي خبرًا ونداء واستفهامًا وأمرًا، ثم اشرح أغراضها بحسب سياق التدريب."},{"n":12,"skill":"مهارات الزيارة والحوار اللبق","passage":"في زيارة تدريبية قال ممثل الفريق: «نشكركم على الاستقبال. هل تسمحون لنا بطرح سؤالين عن إجراءات السلامة؟». يعرّف الضيف بنفسه ويستأذن ويصغي للإجابة، ثم يشكر الطرف الآخر قبل الانصراف.","prompt":"ما الخطوة التي تسبق طرح الأسئلة في المثال؟","correct":"الاستئذان بأدب","w1":"مقاطعة المضيف","w2":"تجاهل التعريف","w3":"بدء التصوير دون موافقة","practice":"أعد حوارًا تمثيليًا للزيارة المهنية من ثماني مداخلات، يتضمن تحية واستئذانًا وسؤالين وخاتمة مناسبة."}]'::jsonb) AS x(
    n integer,skill text,passage text,prompt text,correct text,w1 text,w2 text,w3 text,practice text
  ) LOOP
    SELECT l.id,l.content INTO STRICT target_id,target_content
    FROM public.lessons l
    JOIN public.units u ON u.id=l.unit_id
    JOIN public.grades g ON g.id=u.grade_id AND g.grade_number=10
    JOIN public.curricula cu ON cu.id=g.curriculum_id AND cu.academic_year='2026-2027' AND cu.id='e15ed6fd-370c-4980-b724-d0c19ec2c029'
    JOIN public.countries c ON c.id=cu.country_id AND c.code='BH'
    WHERE u.title='عرب 802 — اللغة العربية للتعليم الفني والمهني' AND u.semester=2 AND l.sort_order=r.n AND l.status='published'
    FOR UPDATE OF l;
    IF char_length(coalesce(target_content,''))<350 THEN
      UPDATE public.lessons SET
        content='ضاديوم — إثراء مستقل أصلي للصف الثامن، الفصل الثاني. لا يمثل النص الوزاري الأصلي ولا يثبت مطابقة العنوان للمصدر.'||E'\n\n'||
          'المهارة: '||r.skill||E'\n\n'||
          'النموذج التعليمي والشرح: '||r.passage||E'\n\n'||
          'أهداف التعلم: يحدد المتعلم شاهدًا صحيحًا ويشرح دلالته، ويميّز بين الفكرة والدليل، ثم ينتج كتابة مناسبة للمهارة.'||E'\n\n'||
          'سؤال الفهم: '||r.prompt||E'\n\n'||
          'التطبيق الكتابي: '||r.practice||E'\n\n'||
          'التمايز: المبتدئ يحصل على كلمات مفتاحية وبداية جملة؛ المتوسط يجيب بدليل مستقل؛ المتقدم يقارن بين صياغتين ويبرر تحسيناته.'||E'\n\n'||
          'مراجعة المعلم: تحقق من صحة الاستدلال والإملاء وعلامات الترقيم والترابط. لا تُمنح درجة جودة تلقائية لمجرد تسليم المهمة.'||E'\n\n'||
          'تنبيه المصدر: راجع العنوان المستورد والكتاب الرسمي قبل وصف هذا التدريب بأنه مطابق للمنهج.'||E'\n\n'||'المدخل السابق المحفوظ: '||coalesce(target_content,''),
        updated_at=now()
      WHERE id=target_id;
    END IF;
    IF EXISTS (SELECT 1 FROM public.lessons WHERE id=target_id AND content LIKE 'ضاديوم — إثراء مستقل أصلي للصف الثامن%') THEN
      INSERT INTO public.lesson_activities (lesson_id,title,activity_type,section,prompt,content,answer,activity_order,points,is_required,is_published)
      SELECT target_id,'فهم النص الإثرائي','multiple_choice','assessment',r.prompt,
        jsonb_build_object('origin','DADYOOM_BH_TECH_G10_T2_ARAB802_ORIGINAL_20261008','notOfficialBook',true,'ocrReview','pending','options',jsonb_build_array(r.correct,r.w1,r.w2,r.w3)),
        jsonb_build_object('correct',r.correct),
        coalesce((SELECT max(activity_order) FROM public.lesson_activities WHERE lesson_id=target_id),0)+1,5,true,true
      WHERE NOT EXISTS (SELECT 1 FROM public.lesson_activities WHERE lesson_id=target_id AND activity_type='multiple_choice' AND content->>'origin'='DADYOOM_BH_TECH_G10_T2_ARAB802_ORIGINAL_20261008');
      INSERT INTO public.lesson_activities (lesson_id,title,activity_type,section,prompt,content,answer,activity_order,points,is_required,is_published)
      SELECT target_id,'كتابة تطبيقية بمراجعة المعلم','writing','practice',r.practice,
        jsonb_build_object('origin','DADYOOM_BH_TECH_G10_T2_ARAB802_ORIGINAL_20261008','notOfficialBook',true,'humanReviewRequired',true,'text',r.practice,'skillQualityAutoVerified',false),
        jsonb_build_object('grading_mode','completion_only_reference','model_answer','لا تكفي المطابقة النصية؛ يصحح المعلم ملاءمة الأفكار والدليل والترابط.'),
        coalesce((SELECT max(activity_order) FROM public.lesson_activities WHERE lesson_id=target_id),0)+1,5,true,true
      WHERE NOT EXISTS (SELECT 1 FROM public.lesson_activities WHERE lesson_id=target_id AND activity_type='writing' AND content->>'origin'='DADYOOM_BH_TECH_G10_T2_ARAB802_ORIGINAL_20261008');
    END IF;
  END LOOP;
END
$dadyoom$;